int n, e[N], s[M], wf[K], q[N][K], f[N][N], ans[N][M];
doge op, wq[N][M];
unordered_map<doge,int> rt[N];

int input_number() {
    int res=0; char ch=getchar();
    while(ch<'0' || ch>'9') ch=getchar();
    while(ch>='0' && ch<='9') {
        res=res*10+ch-'0';
        ch=getchar();
    }
    return res;
