long long mod_pow(long long base, int exp) {
    long long result=1;
    while(exp>0) {
        if(exp&1) result=(result*base)%p;
        base=(base*base)%p;
        exp>>=1;
    }
    return result;
}

void handle_node(int u) {
    q[u][0]=0; int count_os=0, count_of=0;
    for(int i=0; i<(1<<n); i++) if(s[i]==u) {
        q[u][++q[u][0]]=i; wf[i]=++count_os;
    }
    for(int i=1; i<=e[u-1]; i++) {
