                        }
                    }
                }
            }
            if(!changed) continue;
            int pos;
            if(rt[u][hc]==0) {
                rt[u][hc]=++count_of; e[u]++; wq[u][e[u]]=hc;
            }
            pos=rt[u][hc];
            ans[u][pos]=(ans[u][pos]+prob*ans[u-1][i])%p;
        }
    }
