import java.util.*;
import java.io.*;

public class Main {
    static final int N = 10;
    static final int M = 1000007;
    static final int K = 200;
    static final int p = 1000000007;
    static int n;
    static int[] e = new int[N];
    static int[] s = new int[M];
    static int[] wf = new int[K];
    static int[][] q = new int[N][K];
    static int[][] f = new int[N][N];
    static int[][] ans = new int[N][M];
    static BitSet[] op = new BitSet[40];
    static BitSet[][] wq = new BitSet[N][M];
    static Map<BitSet, Integer>[] rt = new HashMap[N];

    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    static int inputNumber() throws IOException {
        while (true) {
            String line = br.readLine();
            if (line != null) {
                st = new StringTokenizer(line);
                if (st.hasMoreTokens()) {
                    return Integer.parseInt(st.nextToken());
                }
            }
        }
    }

    static long modPow(long base, int exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % p;
            base = (base * base) % p;
            exp >>= 1;
        }
        return result;
    }

    static void handleNode(int u) {
        q[u][0] = 0;
        int count_os = 0, count_of = 0;
        for (int i = 0; i < (1 << n); i++) {
            if (s[i] == u) {
                q[u][++q[u][0]] = i;
                wf[i] = ++count_os;
            }
        }
        for (int i = 1; i <= e[u - 1]; i++) {
            if (ans[u - 1][i] == 0) continue;
            for (int h = 1; h < (1 << n); h++) {
                long prob = 1;
                for (int c = 0; c < n; c++) {
                    if (((1 << c) & h) != 0) {
                        prob = (prob * f[u][c + 1]) % p;
                    } else {
                        prob = (prob * ((p + 1 - f[u][c + 1]) % p)) % p;
                    }
                }
                BitSet c = (BitSet) wq[u - 1][i].clone();
                BitSet hc = new BitSet(40);
                boolean changed = false;
                for (int x = 1; x <= q[u - 1][0]; x++) {
                    if (c.get(x - 1)) {
                        for (int t = 0; t < n; t++) {
                            if (((1 << t) & h) != 0 && !q[u - 1][x - 1].test(1 << t)) {
                                hc.set(wf[q[u - 1][x - 1] | (1 << t)]);
                                changed = true;
                            }
                        }
                    }
                }
                if (!changed) continue;
                int pos;
                if (!rt[u].containsKey(hc)) {
                    rt[u].put(hc, ++count_of);
                    e[u]++;
                    if (wq[u][0] == null) {
                        wq[u][0] = new BitSet[M];
                    }
                    wq[u][e[u]] = (BitSet) hc.clone();
                }
                pos = rt[u].get(hc);
                ans[u][pos] = (int) ((ans[u][pos] + prob * ans[u - 1][i]) % p);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        n = inputNumber();
        for (int i = 0; i <= (1 << n); i++) {
            s[i] = Integer.bitCount(i);
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                f[i][j] = inputNumber() * (int) modPow(100, p - 2) % p;
            }
        }
        // Initialize
        for (int i = 0; i < N; i++) {
            rt[i] = new HashMap<>();
        }
        q[0][0] = 1;
        e[0] = 1;
        ans[0][1] = 1;
        wq[0][1] = new BitSet[1];
        wq[0][1][0] = new BitSet(40);
        wq[0][1][0].set(0);
        for (int i = 1; i <= n; i++) {
            handleNode(i);
        }
        System.out.println(ans[n][1]);
    }
}
